import{_ as e,o as t,c as a,a3 as _}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"你在明白什么道理后，你不再焦虑了？","description":"","frontmatter":{},"headers":[],"relativePath":"books/articles/03-你在明白什么道理后，你不再焦虑了？.md","filePath":"books/articles/03-你在明白什么道理后，你不再焦虑了？.md","lastUpdated":1794991578000}'),o={name:"books/articles/03-你在明白什么道理后，你不再焦虑了？.md"};function r(s,p,n,c,l,i){return t(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="你在明白什么道理后-你不再焦虑了" tabindex="-1">你在明白什么道理后，你不再焦虑了？ <a class="header-anchor" href="#你在明白什么道理后-你不再焦虑了" aria-label="Permalink to &quot;你在明白什么道理后，你不再焦虑了？&quot;">​</a></h1><blockquote><p>📌 来源：<a href="https://www.zhihu.com/question/7694586734/answer/2104891457228239199" target="_blank" rel="noreferrer">知乎</a> · 作者：幼儿园大班长 · 收录于 2026-11-18</p></blockquote><p>我有个朋友，看完《明朝那些事》，激动得睡不着觉。逢人就说：成功只有一种，就是按照自己的方式度过一生！</p><p>然后辞职去开民宿，赔了八十万。</p><p>他跑来问我：难道我理解错了？</p><p>我说：你没理解错，但你只看到了最后一页的鸡汤，没看懂前面276年的砒霜。</p><p>当年明月写了五年，把一个朝代的兴衰，十七个皇帝，上万个人物，熬成了一本书。他在最后一页告诉你，要按自己的方式活。但他在前几百页，其实一直在说另一句话：“在这之前，你得先看清，你活在一个什么样的世界里。”</p><p>看完你就知道，为什么有人能活成徐霞客，而大多数人只能活成被推上刑场的袁崇焕。</p><p>第一件：历史就是一台绞肉机，专吃有本事的人。</p><p>你先数数，明朝276年，出了多少牛人？</p><p>朱元璋，朱棣，于谦，王阳明，张居正，威继光，海瑞，袁崇焕……随便拎一个出来，都是能进历史书的人物。但你猜他们什么下场？</p><p>朱元璋杀光了所有帮他打天下的兄弟，晚年看谁都像要造反。于谦救了整个大明朝，转头就被新皇帝砍了头，抄家时兜里比脸还干净，王阳明立德立功立言全占齐了，结果一辈子被贬来贬去，最后死在了回家的路上。张居正把快倒闭的大明强行续命五十年，死后被人挖出来清算，家属饿死的饿死，流放的流放。袁崇焕守住了东北防线，被崇祯一刀一刀剐了，剐了三千六百刀。</p><p>发现规律没？越是有理想，有本事，想干事儿的人，死得越惨。反倒是那些混日子的，会拍马屁的，谁也不得罪的，平平安安活到老。</p><p>这就是当年明月看透的第一件事：历史这台绞肉机，不挑食。它尤其喜欢吃那些想改变它的人。</p><p>那你可能问了：既然这样，还当什么理想主义者？</p><p>别急，往下看。</p><p>第二件：权力是击鼓传花，谁拿到谁倒霉。</p><p>你觉得皇帝权力最大？朱元璋也这么想。他废了宰相，设了锦衣卫，分了藩王，编了《大诰》，把权力的网织得跟铁桶似的，以为自己能干秋万代。</p><p>结果呢？他刚死，他儿子未棣就造了孙子的反。后来的皇帝，有的被太监活活饿死，有的二十多年不上班，有的被人从龙椅上拉下来。皇位这个鼓，传到最后传到崇祯手里，“咚”一声，鼓停了，花在他手上，他得上吊。</p><p>你以为你在追逐权力？其实你追的是一个幻影。你以为你抓住了它，其实是它抓住了你，把你往悬崖底下拽。</p><p>明朝那些内阁首辅，司礼监掌印太监，哪一个不是人精中的人精？最后呢？严嵩饿死街头，魏忠贤被逼自杀，张居正被抄家。权力这玩意儿，拿一天算一天，千万别以为它是你的。</p><p>第三件：历史的剧本早就写好了，你只是演员，我们总喜欢说“如果”。</p><p>如果朱允炆心狠一点，朱棣能成功？如果于谦没被杀，明朝会不会不一样？如果张居正多活十年……如果崇祯不杀袁崇焕……当年明月写了五年，得出了一个让你绝望的结论：这些“如果”，全都不成立。不是老天爷偏心，是人性太固定了。</p><p>朱允炆从小被教“仁义礼智信”，你让他对自己亲叔叔下杀手？他做不到。于谦那么清廉那么刚，不结党不贪腐，这种人放在官场里，就是所有人的眼中钉，他迟早得死。崇祯那个性格，多疑，急躁，刚愎自用，他不杀袁崇焕才叫见鬼。</p><p>每个人的选择看起来是自由的，其实早就被他的出身，性格，环境，教育给定死了。你把他放到那个位置上，一万次里他有九千九百九十九次会做出同样的选择。</p><p>当无数人的“必然选择”叠加在一起，就变成了历史的洪流。你一个人在里面扑腾，想改变方向？门都没有。那还能做什么？</p><p>第四件：制度长着长着，就变成了怪物。</p><p>朱元璋当年设计“言官”制度，让一帮品级不高的小官可以弹劾任何人，目的是防止大臣腐败。听着挺美吧？两百年后，言官变成了什么？变成了党争的武器。变成了刷名声的工具。你想出名？弹劾首辅去，不管对不对，先混个“不畏权贵”的头衔。</p><p>弹劾来弹劾去，朝堂变成了菜市场，真正做事的人反而天天被骂。科举制度，本来是为了选人才，最后把天下读书人的脑子都装进了八股文的牢笼里。卫所制度。本来是为了守边疆，最后士兵变成了农奴，将领变成了地主。</p><p>任何制度，只要是人设计的，就一定有人能找到漏洞。找到漏洞就开始钻，钻的人多了，漏洞就变成黑洞，最后把整个制度给吞了。更可笑的是，想修补制度的人，往往自己也靠这个制度吃饭。你让他改革？等于让他自杀。</p><p>所以大多数人选择装死，直到整个王朝完蛋。明朝就是这么没的。</p><p>第五件：理想主义者，就是用来燃烧的。</p><p>当年明月写于谦，写张居正，写王阳明，写得最动情，但他也发现了一个特别讽刺的事。</p><p>于谦为什么能在土木堡之变后力挽狂澜？因为那时候大明朝快完了，没人敢上，就他敢。可等危机一过，于谦就变成多余的人了。他太干净了，干净到让别人没法活。所以他必须死，张居正为什么能推行改革？因为明朝已经烂到根了，不改革马上死。他硬扛了十年，把帝国从ICU里拉了出来。可他一死，所有被他得罪过的人立刻反扑。</p><p>他必须被清算，否则那些人晚上睡不着觉。理想主义者的宿命就是：只有在火灾的时候大家才需要你，火灭了，你就是那个多余的人。</p><p>更深的讽刺是：正因为大多数人都是自私的，软弱的，妥协的，才显得于谦他们那么珍贵。如果人都是理想主义者，那他们就不会被记住。他们用自己的燃烧，照亮了一瞬间的黑暗。而他们自己知道会烧成灰，但还是选择点着了。</p><p>第六件：那活着还有什么意思？徐霞客给了答案。</p><p>写到这儿，你可能觉得太绝望了：历史是绞肉机，权力是烫手山芋，剧本改不了，制度全是怪物，理想主义者没好下场，那还活个什么劲儿？</p><p>当年明月也想到了这个问题。所以他在全书的最后一卷，没有写崇祯上吊，而是写了一个人。</p><p>徐霞客。</p><p>一个没有任何官职，没有任何功业，没参与过任何权力斗争的人。就是一个旅行者，花了三十年，走了大半个中国，写了一本游记。</p><p>他没改变历史，没救任何人，没留下什么名言警句。但他按自己的方式，过完了一辈子。</p><p>当年明月写了十七个皇帝，无数猛人，两百七十六年的杀戮和权谋之后，终于明白了一件事：那些都不重要。朱元障的权力，他死后就没了。张居正的财富，抄家后一分不剩。于谦的名声，被杀的时候满朝文武没一个敢替他说话。真正重要的，就一件事：你这辈子，有没有为自己活？</p><p>大多数人一辈子都在追求别人定义的成功：多少钱，多大官，多出名。他们活在别人的期待里，从来没问过自己：我到底想要什么？徐霞客知道，他想要山河万里，于是他就去了。饿了就饿着。冷了就当锻炼，被抢了就认栽，差点死了也无所谓。他从没后悔。</p><p>所以当年明月说的“成功只有一种，按照自己的方式度过一生”，不是让你辞职去旅行。而是让你在看清了这五把刀之后（历史是绞肉机，权力是幻影，剧本改不了，制度会烂掉，理想没好下场），依然能说出一句：那又怎样？我还是选择走自己的路。</p><p>于谦选择清白，所以他宁死不屈。王阳明选择知行合一，所以他至死不渝。张居正选择改革，所以他明知会被清算也要干。徐霞客选择山川大江，所以他用一生去丈量大地。他们都知道结局，但他们还是选了。这，才是当年明月从明朝那些事儿里，挖出来的终极天道。</p><p>你的路，你自己走。哪怕最后只留下一行游记，一声叹息，那也是你的。比那些一辈子坐在莲花座上，动都不敢动的人，强一万倍。</p><p>世间万事，不过如此。满纸荒唐言，痴人说梦，也不过痴人二字。</p><p>既如此，便如此！</p>',49)])])}const h=e(o,[["render",r]]);export{f as __pageData,h as default};
